import { BaseException } from '@game-studio/exceptions';
import { Locale } from '../../types';

export interface IExceptionData {
    propertyName: string;
    sourceType: string;
    targetType: string;
}

export class TypeMismatchException extends BaseException<IExceptionData> {
    constructor(propertyName: string, sourceType: string, targetType: string) {
        super('MapAndValidate.TypeMismatchException', `Automapping failed for property ${propertyName}. Expected ${targetType} but received ${sourceType}`, {
            propertyName,
            sourceType,
            targetType
        });
    }

    public localise(locale: Locale): void {
        this.buttonText = this.getButtonText(locale);
        this.displayMessage = this.getGenericErrorMessage(locale);
    }
}
